/*
 * Tests for the per-language lists of the lowering and evaluator part
 * registries (src/xpath_lower_internal.h, src/evaluator_machine_internal.h,
 * generated by cmake/SxmlParts.cmake; D101, D103, D227). The library
 * part registry's lists are tested in tests/function_library_parts_test.c.
 *
 * Golden file: tests/function_library_parts_test.c
 * (test_language_lists_follow_the_registry). Each language's list must be
 * the registered parts that serve it, in registry order; the languages
 * CMake read for a lowering part must be its .languages; and XPath's lists
 * must hold no XQuery-only or XSLT-only part, which is what keeps them
 * out of a module that offers only XPath.
 */
#include "evaluator_machine_internal.h"
#include "function_library_parts_internal.h"
#include "test_runner.h"
#include "xpath_lower_internal.h"

#include <stdbool.h>
#include <string.h>

static sxml_byte_view text_view(const char *text) {
    return (sxml_byte_view){.bytes = (const uint8_t *)text, .byte_count = strlen(text)};
}

static const sxml_language languages[] = {SXML_LANGUAGE_XPATH, SXML_LANGUAGE_XQUERY,
                                          SXML_LANGUAGE_XSLT};

/* ----------------------------------------------------------- Lowering */

static sxml_xpath_lowering_part_view lowering_list(sxml_language language) {
    switch (language) {
    case SXML_LANGUAGE_XPATH:
        return *sxml_xpath_lowering_xpath_parts();
    case SXML_LANGUAGE_XQUERY:
        return *sxml_xpath_lowering_xquery_parts();
    case SXML_LANGUAGE_XSLT:
        return *sxml_xpath_lowering_xslt_parts();
    }
    return (sxml_xpath_lowering_part_view){.parts = NULL, .part_count = 0};
}

static void test_lowering_languages_agree(sxml_test_state *state) {
    const sxml_xpath_lowering_part_view registered = sxml_xpath_lowering_registered_parts();
    SXML_TEST_EXPECT(state, registered.part_count > 0);
    for (size_t part_index = 0; part_index < registered.part_count; part_index += 1) {
        const sxml_xpath_lowering_registered_part *entry = &registered.parts[part_index];
        SXML_TEST_REQUIRE(state, entry->part != NULL);
        SXML_TEST_EXPECT(state, entry->languages != 0 &&
                                    (entry->languages & ~SXML_LANGUAGE_SET_ALL) == 0);
        SXML_TEST_EXPECT(state, entry->languages == entry->part->languages);
    }
}

static void test_lowering_lists_follow_the_registry(sxml_test_state *state) {
    const sxml_xpath_lowering_part_view registered = sxml_xpath_lowering_registered_parts();
    for (size_t language_index = 0; language_index < SXML_TEST_COUNT(languages);
         language_index += 1) {
        const sxml_language language = languages[language_index];
        const sxml_xpath_lowering_part_view list = lowering_list(language);
        SXML_TEST_REQUIRE(state, list.parts != NULL);
        size_t list_index = 0;
        for (size_t part_index = 0; part_index < registered.part_count; part_index += 1) {
            const sxml_xpath_lowering_registered_part *entry = &registered.parts[part_index];
            if ((entry->languages & (sxml_language_set)language) == 0) {
                continue;
            }
            SXML_TEST_EXPECT(state, list_index < list.part_count &&
                                        list.parts[list_index].part == entry->part &&
                                        sxml_byte_view_equals(list.parts[list_index].part_name,
                                                              entry->part_name));
            list_index += 1;
        }
        SXML_TEST_EXPECT(state, list_index == list.part_count);
        /* The zero entry after the last. */
        SXML_TEST_EXPECT(state, list.parts[list.part_count].part == NULL);
    }
}

static bool lowering_list_has(sxml_xpath_lowering_part_view list, const char *part_name) {
    for (size_t part_index = 0; part_index < list.part_count; part_index += 1) {
        if (sxml_byte_view_equals(list.parts[part_index].part_name, text_view(part_name))) {
            return true;
        }
    }
    return false;
}

/* XQuery's own parts are not XPath's (XQuery 4.0's FLWOR clauses, XQuery
   Update, Full Text), and computed constructors (XPath 4.0, 4.13) are. */
static void test_xpath_lowering_list_has_no_xquery_part(sxml_test_state *state) {
    const sxml_xpath_lowering_part_view xpath = *sxml_xpath_lowering_xpath_parts();
    const sxml_xpath_lowering_part_view xquery = *sxml_xpath_lowering_xquery_parts();
    static const char *const xquery_only[] = {"xquery", "update", "full_text"};
    for (size_t name_index = 0; name_index < SXML_TEST_COUNT(xquery_only); name_index += 1) {
        SXML_TEST_EXPECT(state, lowering_list_has(xquery, xquery_only[name_index]));
        SXML_TEST_EXPECT(state, !lowering_list_has(xpath, xquery_only[name_index]));
    }
    SXML_TEST_EXPECT(state, lowering_list_has(xpath, "construct"));
}

/* ---------------------------------------------------------- Evaluator */

static sxml_evaluator_registered_part_view evaluator_list(sxml_language language) {
    switch (language) {
    case SXML_LANGUAGE_XPATH:
        return *sxml_evaluator_xpath_parts();
    case SXML_LANGUAGE_XQUERY:
        return *sxml_evaluator_xquery_parts();
    case SXML_LANGUAGE_XSLT:
        return *sxml_evaluator_xslt_parts();
    }
    return (sxml_evaluator_registered_part_view){.parts = NULL, .part_count = 0};
}

static void test_evaluator_lists_follow_the_registry(sxml_test_state *state) {
    const sxml_evaluator_registered_part_view registered = sxml_evaluator_registered_parts();
    SXML_TEST_EXPECT(state, registered.part_count > 0);
    for (size_t part_index = 0; part_index < registered.part_count; part_index += 1) {
        const sxml_language_set part_languages = registered.parts[part_index].languages;
        SXML_TEST_EXPECT(state, part_languages != 0 &&
                                    (part_languages & ~SXML_LANGUAGE_SET_ALL) == 0);
    }
    for (size_t language_index = 0; language_index < SXML_TEST_COUNT(languages);
         language_index += 1) {
        const sxml_language language = languages[language_index];
        const sxml_evaluator_registered_part_view list = evaluator_list(language);
        SXML_TEST_REQUIRE(state, list.parts != NULL);
        size_t list_index = 0;
        for (size_t part_index = 0; part_index < registered.part_count; part_index += 1) {
            const sxml_evaluator_registered_part *entry = &registered.parts[part_index];
            if ((entry->languages & (sxml_language_set)language) == 0) {
                continue;
            }
            SXML_TEST_EXPECT(state, list_index < list.part_count &&
                                        list.parts[list_index].part == entry->part &&
                                        sxml_byte_view_equals(list.parts[list_index].part_name,
                                                              entry->part_name));
            list_index += 1;
        }
        SXML_TEST_EXPECT(state, list_index == list.part_count);
        SXML_TEST_EXPECT(state, list.parts[list.part_count].part == NULL);
    }
}

static const sxml_test_case part_registry_test_cases[] = {
    {.name = "lowering_languages_agree", .function = test_lowering_languages_agree},
    {.name = "lowering_lists_follow_the_registry",
     .function = test_lowering_lists_follow_the_registry},
    {.name = "xpath_lowering_list_has_no_xquery_part",
     .function = test_xpath_lowering_list_has_no_xquery_part},
    {.name = "evaluator_lists_follow_the_registry",
     .function = test_evaluator_lists_follow_the_registry},
};

int main(int argument_count, char **arguments) {
    return sxml_test_run_suite(
        &(sxml_test_suite){
            .name = "part_registry",
            .cases = part_registry_test_cases,
            .case_count = SXML_TEST_COUNT(part_registry_test_cases),
        },
        (sxml_test_command_line){
            .argument_count = argument_count,
            .arguments = arguments,
        });
}
